# owner: platform
from hourglass.parsing import format_span, format_clock
from hourglass.merging import merge_spans


def _check_inside(spans, opening):
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"outside opening: {format_span(span)}")


def _uncovered(spans, opening):
    points = [opening.start]
    for span in spans:
        points += [span.start, span.end]
    points.append(opening.end)
    return list(zip(points[::2], points[1::2]))


def _label(start, end):
    clocks = f"{format_clock(start)}-{format_clock(end)}"
    return f"gap {clocks} ({end - start} min)"


# ---
def find_gaps(worked, opening):
    spans = merge_spans(worked)
    _check_inside(spans, opening)
    pairs = _uncovered(spans, opening)
    return [_label(a, b) for a, b in pairs if a < b]
